test('rapid transcript fragments coalesce into one latest adaptive revision while still live',async t=>{
 let reasoningInFlight=0,maxConcurrent=0;const f=await setup({synthetic:true,audioDelay:5,coachDelay:()=>{reasoningInFlight++;maxConcurrent=Math.max(maxConcurrent,reasoningInFlight);return 160;},audioText:body=>`SYNTHETIC transport fragment ${body.sequence}.`,responseAnalysis:body=>{reasoningInFlight--;return adaptiveAnswer(body);}});
 try{await start(f);for(let i=0;i<12;i++)await f.chunk();await waitFor(f,()=>{const stats=diagnostics(f);return stats.transcriptTranscribed===12&&stats.adaptiveReasoningJobsStarted>=2&&stats.adaptiveReasoningJobsCompleted===stats.adaptiveReasoningJobsStarted;});const stats=diagnostics(f),requests=f.calls.filter(call=>call.action==='coach');assert.equal(maxConcurrent,1,'only one adaptive reasoning request runs at once');assert.equal(stats.transcriptTranscribed,12);assert.ok(stats.adaptiveReasoningJobsStarted>=2);assert.equal(stats.adaptiveReasoningJobsCompleted,stats.adaptiveReasoningJobsStarted);assert.ok(stats.adaptiveReasoningCoalescedSnapshots>=1);assert.ok(stats.adaptiveModelRevision>=1,'the accepted latest snapshot advances the model once after coalescing intermediate fragments');assert.equal(stats.recommendationExists,true);assert.match(JSON.stringify(f.tree.toJSON()),/Recommended now/,'useful coaching is visible before the call ends');assert.ok(requests.at(-1).segments.some(row=>row.id==='11'),'the final accepted request sees the latest complete transcript');assert.ok(requests.at(-1).segments.some(row=>row.id==='11'),'the final accepted request carries the latest transcript snapshot');assert.ok(stats.adaptiveReasoningAverageLatencyMs>=160);assert.equal(f.calls.filter(call=>['approve','task','calendar'].includes(call.action)).length,0);t.diagnostic(`rolling reasoning fixture: ${stats.adaptiveReasoningJobsStarted} started / ${stats.adaptiveReasoningJobsCompleted} completed; average ${stats.adaptiveReasoningAverageLatencyMs}ms; 12 transcript fragments; maximum concurrent requests ${maxConcurrent}`);
 }finally{await act(()=>f.tree.unmount());}
});
