test('lossless transcript backlog finalises every captured segment while coaching coalesces stale work',async t=>{
 const count=12,wording='Ask: “Which day later next week works best for the second conversation?”';
  const responseAnalysis=body=>body.sequence===count-1?{...model,questions:[{text:wording,wording,goal:'Ask for a specific day for the second conversation.',lead:'They agreed to meet again and have said later next week suits them.',quote:`SYNTHETIC segment ${count-1}. No budget is signed off; spend is tight.`,segmentId:String(count-1),priority:'critical',branch:'follow_up',angle:'next_step'}]}:{...model,questions:[]};
 const audioTrace=body=>body.sequence===count-1?[{stage:'opportunity_detected',at:Date.now(),sequence:body.sequence,signals:['check_close'],priority:'critical'}]:[];
  const f=await setup({synthetic:true,audioDelay:45,coachDelay:180,audioText:body=>`SYNTHETIC segment ${body.sequence}. No budget is signed off; spend is tight.`,responseAnalysis,audioTrace});await start(f);for(let i=0;i<count;i++)await f.chunk();await act(async()=>{await new Promise(resolve=>setTimeout(resolve,280));});
 const finalisingStarted=Date.now();await act(()=>button(f,'End meeting').props.onClick());await flush();let rendered=JSON.stringify(f.tree.toJSON());
 assert.match(rendered,/Finalising transcript/,'hang-up waits for pending speech transcription');assert.doesNotMatch(rendered,/Meeting review/,'review is not shown as final while captured audio is pending');assert.equal(f.calls.filter(c=>c.action==='review').length,0,'no review request before transcript finalisation');
 while(!/Meeting review/.test(rendered)&&Date.now()-finalisingStarted<5000){await act(async()=>{await new Promise(resolve=>setTimeout(resolve,10));});rendered=JSON.stringify(f.tree.toJSON());}const finalisationMs=Date.now()-finalisingStarted;assert.match(rendered,/Meeting review/,'meeting review appears after all captured speech has finalised');const audioCalls=f.calls.filter(c=>c.action==='audio'),review=f.calls.find(c=>c.action==='review'),preText=f.tree.root.findAllByType('pre').map(node=>node.children.join('')).join('\n');
 assert.deepEqual(audioCalls.map(call=>call.sequence),Array.from({length:count},(_,i)=>i),'every captured audio segment is sent for transcription in capture order');assert.equal(audioCalls.length,count);assert.deepEqual(review.segments.map(row=>row.id),Array.from({length:count},(_,i)=>String(i)),'final meeting record preserves transcript chronology');assert.deepEqual(review.segments.map(row=>row.text),Array.from({length:count},(_,i)=>`SYNTHETIC segment ${i}. No budget is signed off; spend is tight.`));
  const firstTrace=preText.indexOf('\n{');const stats=JSON.parse(firstTrace<0?preText:preText.slice(0,firstTrace));assert.equal(stats.transcriptCaptured,count);assert.equal(stats.transcriptTranscribed,count);assert.equal(stats.transcriptFailures,0);assert.equal(stats.transcriptLost,0);assert.ok(stats.coachingJobsSuperseded>0,'coalesced coaching is replaced by fresher whole-conversation work before visibility while transcript audio remains lossless');assert.equal(f.calls.filter(c=>c.action==='approve'||c.action==='task'||c.action==='calendar').length,0,'synthetic capture performs zero canonical/Diary/Calendar writes');
 assert.ok(stats.medianHighPriorityDetectionToVisibleMs===null||stats.medianHighPriorityDetectionToVisibleMs>=0);assert.equal(audioCalls.at(-1).sequence,count-1);assert.equal(audioCalls.filter(call=>call.sequence<0).length,0);assert.ok(finalisationMs<5000);t.diagnostic(`backlog finalisation: ${count} captured, ${stats.transcriptTranscribed} transcribed, ${stats.transcriptFailures} failed, ${stats.transcriptLost} lost, ${stats.promptsSuppressedMissedWindow} stale coaching prompts suppressed before visibility; finalisation ${finalisationMs}ms`);await act(()=>f.tree.unmount());
});

test('substantive finalized close evidence starts reasoning without a silence event',async t=>{
  const path=['The purpose is to decide whether a proper second meeting would be worthwhile.','The second meeting would let us see the detail and how it would work for us.','Send something short that I can share internally.','That is fine, provided it is short. Give me a week or two after receiving it.','Would earlier or later next week be better for the second conversation?','Later next week would be better.'],audioText=body=>path[body.sequence]||'Earlier low-value analysis.',responseAnalysis=body=>body.sequence===5?{...model,questions:[{text:'Ask: “Which day later next week works best for the second conversation?”',wording:'Ask: “Which day later next week works best for the second conversation?”',goal:'Ask for one specific day.',lead:'They have accepted the second meeting and later next week.',quote:path[5],segmentId:'5',priority:'critical',branch:'follow_up',angle:'next_step'}]}:{...model,questions:[]};
  const f=await setup({synthetic:true,audioText,responseAnalysis});try{await start(f);for(let i=0;i<path.length;i++)await f.chunk();await waitFor(f,()=>diagnostics(f).transcriptTranscribed===path.length);await waitFor(f,()=>f.calls.some(call=>call.action==='coach'&&call.sequence===5));await waitFor(f,()=>JSON.stringify(f.tree.toJSON()).includes('Which day later next week works best'));const rendered=JSON.stringify(f.tree.toJSON()),preText=f.tree.root.findAllByType('pre').map(node=>node.children.join('')).join('\n'),stats=diagnostics(f);assert.match(rendered,/Ask: “Which day later next week works best for the second conversation\?”/);assert.equal(stats.silenceRechecks,0,'no silence event is needed to start or surface reasoning');assert.doesNotMatch(preText,/silence_recheck_detected/);assert.match(preText,/adaptive_reasoning_started/);assert.equal(stats.transcriptCaptured,path.length);assert.equal(stats.transcriptTranscribed,path.length);assert.equal(stats.transcriptLost,0);assert.ok(stats.medianHighPriorityDetectionToVisibleMs>=0&&stats.medianHighPriorityDetectionToVisibleMs<4000);assert.ok(stats.worstCriticalDetectionToVisibleMs>=0&&stats.worstCriticalDetectionToVisibleMs<4000);t.diagnostic(`event-driven close: high-priority detection-to-visible ${stats.medianHighPriorityDetectionToVisibleMs}ms; critical worst ${stats.worstCriticalDetectionToVisibleMs}ms; silence rechecks ${stats.silenceRechecks}`);assert.equal(f.calls.filter(call=>call.action==='approve'||call.action==='task'||call.action==='calendar').length,0);await act(()=>button(f,'End meeting').props.onClick());}finally{await act(()=>f.tree.unmount());}
});
test('ordinary live meeting shows the recommended move and Why without synthetic diagnostics',async()=>{const f=await setup();await start(f);await f.chunk();const text=JSON.stringify(f.tree.toJSON());assert.match(text,/Recommended now/);assert.match(text,/How will you measure success/);assert.match(text,/Why/);assert.doesNotMatch(text,/Goal now:|Practice coaching diagnostics/);assert.equal(button(f,'End meeting').props.disabled,false);await act(()=>button(f,'End meeting').props.onClick());await act(()=>f.tree.unmount());});

test('consultative and one-call modes keep the transcript and adaptive coach path',async()=>{
 for(const mode of ['consultative','one_call_close']){const f=await setup({synthetic:true,audioText:`SYNTHETIC ${mode} evidence: the team has a clear operational need.`});try{if(mode!=='consultative')await act(()=>f.tree.root.findByType('select').props.onChange({target:{value:mode}}));await start(f);assert.equal(f.tree.root.findAllByProps({'aria-label':'Meeting transcript'}).length,1);assert.match(JSON.stringify(f.tree.toJSON()),/Listening…/);await f.chunk();await flush();const coach=f.calls.find(call=>call.action==='coach');assert.ok(coach);assert.equal(coach.salesMode,mode);assert.equal(coach.segments[0].text,`SYNTHETIC ${mode} evidence: the team has a clear operational need.`);assert.match(JSON.stringify(f.tree.toJSON()),new RegExp(`SYNTHETIC ${mode} evidence`));}finally{await act(()=>f.tree.unmount());}}
});
